import * as THREE from'three';
let texture;const geometries=new Map(),material=new THREE.MeshBasicMaterial({color:0x000000,transparent:true,opacity:.42,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-1});
export function contactShadow105(width,depth){if(!texture){const w=128,h=64,data=new Uint8Array(w*h*4);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const a=(x/(w-1)-.5)*2,b=(y/(h-1)-.5)*2,alpha=Math.max(0,1-Math.pow(Math.abs(a),6))*Math.exp(-b*b*3.8)*Math.max(0,1-Math.pow(Math.abs(b),8));data[(y*w+x)*4+3]=Math.round(alpha*255);}texture=new THREE.DataTexture(data,w,h);texture.needsUpdate=true;texture.userData.quality100Shared=true;material.map=texture;}const key=width+':'+depth;if(!geometries.has(key))geometries.set(key,new THREE.PlaneGeometry(width,depth));const shadow=new THREE.Mesh(geometries.get(key),material);shadow.rotation.x=-Math.PI/2;shadow.position.y=.03;shadow.name='Sombra_de_contacto105';shadow.userData.contact105=true;shadow.raycast=()=>{};return shadow;}
